#pragma once
#include "day6_containers.h"
#include <boost/property_tree/ptree.hpp>
#include <codecvt>
#include <locale>
#include <sstream>
#include <iomanip>
#include <regex>
#include <cctype>
namespace day6 {
inline std::string trim(std::string s){auto a=s.find_first_not_of(" \t\r\n"),b=s.find_last_not_of(" \t\r\n");return a==std::string::npos?"":s.substr(a,b-a+1);}
inline std::vector<std::string> split(const std::string& s,char d){std::stringstream in(s);std::vector<std::string> out;std::string x;while(std::getline(in,x,d))if(!trim(x).empty())out.push_back(trim(x));return out;}
inline std::vector<std::string> tokens(const std::string& s){std::stringstream in(s);std::vector<std::string> out;std::string x;while(in>>x)out.push_back(x);return out;}
inline int integer(const std::string& s){size_t n=0;int v=std::stoi(s,&n);if(n!=s.size())throw std::invalid_argument("integer expected: "+s);return v;}
inline double real(const std::string& s){size_t n=0;double v=std::stod(s,&n);if(n!=s.size()||!std::isfinite(v))throw std::invalid_argument("number expected: "+s);return v;}
template<class C>std::string join(const C& c,const std::string& d=" "){std::ostringstream o;bool first=true;for(auto& x:c){if(!first)o<<d;first=false;o<<x;}return o.str();}
inline std::u32string u32(const std::string& s){std::wstring_convert<std::codecvt_utf8<char32_t>,char32_t> c;return c.from_bytes(s);}
inline std::string utf8(const std::u32string& s){std::wstring_convert<std::codecvt_utf8<char32_t>,char32_t> c;return c.to_bytes(s);}
inline std::string matrixText(const Matrix<double>& m){std::ostringstream o;for(size_t i=0;i<m.rows();++i){if(i)o<<'\n';for(size_t j=0;j<m.cols();++j)o<<(j?"  ":"")<<m(i,j);}return o.str();}
inline Polynomial<double> parsePoly(std::string s){s.erase(std::remove_if(s.begin(),s.end(),[](unsigned char c){return std::isspace(c);}),s.end());if(s.empty())throw std::invalid_argument("empty polynomial");Polynomial<double> p;size_t i=0;while(i<s.size()){int sign=1;if(s[i]=='+'||s[i]=='-'){sign=s[i]=='-'?-1:1;++i;}size_t a=i;while(i<s.size()&&(std::isdigit((unsigned char)s[i])||s[i]=='.'))++i;double coef=a==i?1:real(s.substr(a,i-a));int degree=0;if(i<s.size()&&s[i]=='x'){degree=1;++i;if(i<s.size()&&s[i]=='^'){++i;size_t b=i;while(i<s.size()&&std::isdigit((unsigned char)s[i]))++i;if(b==i)throw std::invalid_argument("bad exponent at "+std::to_string(i+1));degree=integer(s.substr(b,i-b));}}else if(a==i)throw std::invalid_argument("bad term at "+std::to_string(i+1));if(i<s.size()&&s[i]!='+'&&s[i]!='-')throw std::invalid_argument("bad token at "+std::to_string(i+1));double previous=0;auto it=p.terms().find(degree);if(it!=p.terms().end())previous=it->second;p.set(degree,previous+sign*coef);}return p;}
inline std::string polyText(const Polynomial<double>& p){std::ostringstream o;bool first=true;for(auto it=p.terms().rbegin();it!=p.terms().rend();++it){auto [d,v]=*it;if(std::abs(v)<1e-12)continue;if(!first)o<<(v<0?" - ":" + ");else if(v<0)o<<'-';double a=std::abs(v);if(d==0||std::abs(a-1)>1e-12)o<<a;if(d)o<<'x';if(d>1)o<<'^'<<d;first=false;}return first?"0":o.str();}
inline std::string execute(const boost::property_tree::ptree& p){int variant=p.get<int>("variant");std::string data=p.get<std::string>("data","");std::ostringstream out;
 if(variant==1){LinkedList<int> a;for(auto& c:split(data,';')){auto t=tokens(c);if(t.empty())continue;auto op=t[0];if(op=="push"||op=="push_back"||op=="push_front"){if(t.size()!=2)throw std::invalid_argument("push value");int v=integer(t[1]);if(op=="push_front")a.push_front(v);else a.push_back(v);}else if(op=="pop"||op=="pop_back")out<<"pop: "<<a.pop_back()<<'\n';else if(op=="pop_front")out<<"pop: "<<a.pop_front()<<'\n';else if(op=="reverse")a.reverse();else if(op=="reverseRecursive")a.reverseRecursive();else if(op=="erase"&&t.size()==2){int i=integer(t[1]);if(i<0)throw std::out_of_range("index");a.erase(i);}else if(op=="insert"&&t.size()==3){int i=integer(t[1]);if(i<0)throw std::out_of_range("index");a.insert(i,integer(t[2]));}else throw std::invalid_argument("unknown list command: "+op);}out<<"Список: "<<join(a)<<"\nРозмір: "<<a.size();}
 else if(variant==2){BST<int> a;for(auto& c:split(data,';')){auto t=tokens(c);if(t.size()!=2)throw std::invalid_argument("BST: insert/erase/contains number");int x=integer(t[1]);if(t[0]=="insert")a.insert(x);else if(t[0]=="erase")a.erase(x);else if(t[0]=="contains")out<<x<<": "<<(a.contains(x)?"true":"false")<<'\n';else throw std::invalid_argument("unknown BST command");}std::vector<int> pre,post;a.preorder([&](int x){pre.push_back(x);});a.postorder([&](int x){post.push_back(x);});out<<"inorder: "<<join(a.values())<<"\npreorder: "<<join(pre)<<"\npostorder: "<<join(post)<<"\nВисота: "<<a.height();}
 else if(variant==3){int cap=p.get<int>("capacity",3);if(cap<1||cap>10000)throw std::invalid_argument("capacity 1..10000");RingBuffer<int> a(cap);for(auto& c:split(data,';')){auto t=tokens(c);if(t.empty())continue;if(t[0]=="push"&&t.size()==2)a.push(integer(t[1]));else if(t[0]=="pop"&&t.size()==1)out<<"pop: "<<a.pop()<<'\n';else throw std::invalid_argument("ring: push number / pop");}out<<"Буфер: "<<join(a.values())<<"\nРозмір: "<<a.size();if(!a.empty())out<<"\nfront: "<<a.front()<<"; back: "<<a.back();}
 else if(variant==4){auto lines=split(data,';');if(lines.empty())throw std::invalid_argument("empty matrix");auto first=split(lines[0],',');size_t rows=lines.size(),cols=first.size();if(rows>8||cols>8||!cols)throw std::invalid_argument("matrix max 8x8");Matrix<double> a(rows,cols);for(size_t i=0;i<rows;++i){auto cells=split(lines[i],',');if(cells.size()!=cols)throw std::invalid_argument("ragged matrix");for(size_t j=0;j<cols;++j)a(i,j)=real(cells[j]);}out<<"Матриця:\n"<<matrixText(a)<<"\nТранспонована:\n"<<matrixText(a.transpose());if(rows==cols){out<<"\nВизначник: "<<a.determinant()<<"\nA × A:\n"<<matrixText(a*a);}}
 else if(variant==5){bool min=p.get<std::string>("mode","max")=="min";PriorityQueue<int> maxq;PriorityQueue<int,std::greater<int>> minq;for(auto& c:split(data,';')){auto t=tokens(c);if(t.empty())continue;if(t[0]=="push"&&t.size()==2){int x=integer(t[1]);if(min)minq.push(x);else maxq.push(x);}else if(t[0]=="pop"&&t.size()==1)out<<"pop: "<<(min?minq.pop():maxq.pop())<<'\n';else throw std::invalid_argument("heap: push number / pop");}std::vector<int> v;while(min?!minq.empty():!maxq.empty())v.push_back(min?minq.pop():maxq.pop());out<<"Черга: "<<join(v);std::sort(v.begin(),v.end());out<<"\nheapSort: "<<join(v);}
 else if(variant==6){HashMap<std::string,int> map;std::string word;std::istringstream in(data);while(in>>word){for(char& c:word)if(c>='A'&&c<='Z')c=char(c+32);word.erase(std::remove_if(word.begin(),word.end(),[](unsigned char c){return c<128&&!std::isalnum(c);}),word.end());if(!word.empty())++map[word];}auto v=map.entries();std::sort(v.begin(),v.end(),[](auto& a,auto& b){return a.second!=b.second?a.second>b.second:a.first<b.first;});out<<"Топ-10:\n";for(size_t i=0;i<std::min(size_t(10),v.size());++i)out<<v[i].first<<": "<<v[i].second<<'\n';out<<"Слів: "<<map.size()<<"\nКошиків: "<<map.bucketCount()<<"\nLoad factor: "<<map.loadFactor()<<"\nМакс. ланцюжок: "<<map.longestChain();}
 else if(variant==7){Graph<std::string> g;std::vector<std::pair<std::string,std::string>> edges;for(auto& e:split(data,',')){auto pos=e.find('-');if(pos==std::string::npos)throw std::invalid_argument("edge format A-B");auto a=trim(e.substr(0,pos)),b=trim(e.substr(pos+1));if(a.empty()||b.empty())throw std::invalid_argument("empty vertex");g.addVertex(a);g.addVertex(b);edges.emplace_back(a,b);}for(auto& e:edges)g.addEdge(e.first,e.second);auto start=p.get<std::string>("start","1"),end=p.get<std::string>("end","5");out<<"BFS: "<<join(g.bfs(start)," → ")<<"\nDFS: "<<join(g.dfs(start)," → ")<<"\nШлях: "<<join(g.shortest(start,end)," → ")<<"\nКомпонент: "<<g.components()<<"\nЦикл: "<<(g.hasCycle()?"так":"ні");}
 else if(variant==8){Trie t;for(auto& w:split(data,','))t.insert(u32(w));auto rem=trim(p.get<std::string>("remove",""));if(!rem.empty())t.remove(u32(rem));auto pref=u32(p.get<std::string>("prefix","car"));auto v=t.autocomplete(pref);out<<"Слів: "<<t.size()<<"\nАвтодоповнення: ";for(size_t i=0;i<std::min(size_t(10),v.size());++i)out<<(i?", ":"")<<utf8(v[i]);}
 else if(variant==9){auto a=parsePoly(data),b=parsePoly(p.get<std::string>("q","x-1"));double x=real(p.get<std::string>("x","2"));out<<"P = "<<polyText(a)<<"\nQ = "<<polyText(b)<<"\nP + Q = "<<polyText(a+b)<<"\nP × Q = "<<polyText(a*b)<<"\nP′ = "<<polyText(a.derivative())<<"\nP("<<x<<") = "<<a.evaluate(x);}
 else if(variant==10){int cap=p.get<int>("capacity",2);if(cap<1||cap>10000)throw std::invalid_argument("capacity 1..10000");LRUCache<std::string,std::string> a(cap);for(auto& c:split(data,';')){auto t=tokens(c);if(t.empty())continue;if(t[0]=="put"&&t.size()>=3){a.put(t[1],t[2]);}else if(t[0]=="get"&&t.size()==2){auto x=a.get(t[1]);out<<"get "<<t[1]<<": "<<(x?*x:"miss")<<'\n';}else throw std::invalid_argument("LRU: put key value / get key");}out<<"Нові → старі: ";for(auto& x:a)out<<x.first<<':'<<x.second<<' ';out<<"\nHits: "<<a.hits<<"; misses: "<<a.misses;}
 else throw std::invalid_argument("variant must be 1..10");return out.str();}
}
